server {
    listen 8443 ssl;
    server_name localhost;

    ssl_certificate     /etc/nginx/ssl/server.crt;
    ssl_certificate_key /etc/nginx/ssl/server.key;

    location /dev/ {
        alias /var/www/dev/;
        index index.html;
        autoindex off;
    }

    location / {
        root /var/www/main;
        index index.html;
        autoindex off;
    }
}
